'use strict';
const $=s=>document.querySelector(s);const fmt=x=>Math.abs(x)<0.0000005?'0.000000':Number(x).toFixed(6);
function download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function loadJSON(url){const r=await fetch(url);if(!r.ok)throw Error('Sample unavailable');return r.json()}
if($('#episode-video')){(async()=>{try{const data=await loadJSON('/data/robot/episode.json'),video=$('#episode-video'),slider=$('#frame-slider');let index=0,kind='observation.state',raf;const last=data.frames.length-1;slider.max=last;function render(i){index=Math.max(0,Math.min(last,i));const frame=data.frames[index];slider.value=index;$('#frame-tag').textContent=`FRAME ${String(index).padStart(2,'0')} / ${last}`;$('#time-output').textContent=Number(frame.timestamp).toFixed(1)+' s';$('#show-state').setAttribute('aria-pressed',kind==='observation.state');$('#show-action').setAttribute('aria-pressed',kind==='action');$('#vectors').innerHTML=data.fields[kind].names.map((name,j)=>{const series=data.frames.map(f=>f[kind][j]),min=Math.min(...series),max=Math.max(...series),range=max-min||1;const points=series.map((v,k)=>`${(k/last*100).toFixed(2)},${(21-(v-min)/range*18).toFixed(2)}`).join(' ');const cx=index/last*100,cy=21-(series[index]-min)/range*18;return `<div class="vector-row"><span>${name}</span><svg class="spark" viewBox="0 0 100 25" preserveAspectRatio="none" aria-hidden="true"><path d="M0 22H100" stroke="#e2e5dd" fill="none"/><polyline points="${points}" stroke="#9fae9e" stroke-width="1.3" fill="none"/><line x1="${cx}" x2="${cx}" y1="0" y2="25" stroke="#d5a252" stroke-width=".7"/><circle cx="${cx}" cy="${cy}" r="2" fill="#c97b08"/></svg><span class="value">${fmt(frame[kind][j])}</span></div>`}).join('');$('#record-card').innerHTML=`<div>{</div><div class="record-line"><span class="key">instruction:</span><br><span class="val">“${data.instruction}”</span></div><div class="record-line"><span class="key">frame_index:</span> <span class="em">${index}</span></div><div class="record-line"><span class="key">timestamp:</span> <span class="em">${Number(frame.timestamp).toFixed(1)} s</span></div><div class="record-line"><span class="key">image_0:</span> <span class="em">frame ${index}</span></div><div class="record-line"><span class="key">state:</span> <span class="em">[7 recorded values]</span></div><div class="record-line"><span class="key">action:</span> <span class="em">[7 recorded values]</span></div><div>}</div>`;$('#robot-json').textContent=JSON.stringify({instruction:data.instruction,...frame},null,2)}function sync(){const next=Math.min(last,Math.max(0,Math.floor(video.currentTime*data.fps+0.0001)));if(next!==index)render(next);if(!video.paused)raf=requestAnimationFrame(sync)}function pause(){video.pause();cancelAnimationFrame(raf);$('#play-episode').textContent='▶';$('#play-episode').setAttribute('aria-label','Play episode')}$('#play-episode').onclick=async()=>{if(!video.paused){pause();return}if(video.ended||video.currentTime>=data.video_duration_seconds-.05){video.currentTime=0;render(0)}try{await video.play();$('#play-episode').textContent='Ⅱ';$('#play-episode').setAttribute('aria-label','Pause episode');sync()}catch{$('#time-output').textContent='Use scrubber'}};slider.oninput=()=>{pause();const i=Number(slider.value);video.currentTime=Math.min(data.video_duration_seconds-.01,Number(data.frames[i].timestamp)+.001);render(i)};video.addEventListener('ended',()=>{pause();render(last)});$('#show-state').onclick=()=>{kind='observation.state';render(index)};$('#show-action').onclick=()=>{kind='action';render(index)};document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});render(0)}catch(e){$('#vectors').textContent='Source records could not load. Please reload or download the sample below.'}})()}
// Add the approved Calendly event URL here when scheduling is ready.
const CALENDLY_URL = '';
const schedulerDialog=document.createElement('dialog');
schedulerDialog.className='brief scheduler-dialog';
schedulerDialog.setAttribute('aria-labelledby','scheduler-title');
schedulerDialog.setAttribute('aria-describedby','scheduler-description');
schedulerDialog.innerHTML=`<div class="dialog-top"><p class="eyebrow">A conversation with the founders</p><button class="close" aria-label="Close scheduler preview">×</button></div><h2 id="scheduler-title">Let’s talk about your data.</h2><p id="scheduler-description">The Calendly booking link will be added here. Online scheduling is not live yet.</p><p class="small scheduler-preview-label">Frontend preview · No booking has been made.</p>`;
document.body.append(schedulerDialog);
let schedulerTrigger;
document.querySelectorAll('[data-schedule]').forEach(button=>button.addEventListener('click',()=>{
  if(CALENDLY_URL){window.location.assign(CALENDLY_URL);return;}
  schedulerTrigger=button;schedulerDialog.showModal();
}));
schedulerDialog.querySelector('.close').addEventListener('click',()=>schedulerDialog.close());
schedulerDialog.addEventListener('close',()=>schedulerTrigger?.focus());
schedulerDialog.addEventListener('click',event=>{if(event.target===schedulerDialog){const r=schedulerDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)schedulerDialog.close();}});
if($('#cad-canvas')){(async()=>{const canvas=$('#cad-canvas'),ctx=canvas.getContext('2d');try{const [before,after,checks]=await Promise.all([loadJSON('/data/cad/before.mesh.json'),loadJSON('/data/cad/after.mesh.json'),loadJSON('/data/cad/validation.json')]);let phase='before',yaw=-.55,pitch=.9,drag=null;function draw(){const rect=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,rect.width,rect.height);const mesh=phase==='before'?before:after,scale=Math.min(rect.width/150,rect.height/140),c=Math.cos(yaw),s=Math.sin(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch);const transformed=mesh.vertices.map(([x,y,z])=>{const rx=x*c-y*s,ry=x*s+y*c;return [rect.width/2+rx*scale,rect.height/2+(ry*sp-z*cp)*scale,ry*cp+z*sp]});const faces=mesh.triangles.map(t=>{const a=mesh.vertices[t[0]],b=mesh.vertices[t[1]],d=mesh.vertices[t[2]],u=b.map((v,i)=>v-a[i]),v=d.map((v,i)=>v-a[i]),n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],len=Math.hypot(...n)||1;const light=Math.abs((n[0]*-.3+n[1]*-.4+n[2]*.86)/len),shade=Math.round(142+light*69);return {t,z:(transformed[t[0]][2]+transformed[t[1]][2]+transformed[t[2]][2])/3,shade}}).sort((a,b)=>a.z-b.z);for(const f of faces){ctx.beginPath();f.t.forEach((i,j)=>{const p=transformed[i];j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])});ctx.closePath();ctx.fillStyle=`rgb(${f.shade-3},${f.shade+4},${f.shade-7})`;ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.35;ctx.stroke()}const r=checks[phase].center_hole_diameter_mm/2;ctx.beginPath();for(let k=0;k<=80;k++){const angle=k/80*Math.PI*2,x=Math.cos(angle)*r,y=Math.sin(angle)*r,z=5.02,rx=x*c-y*s,ry=x*s+y*c;const px=rect.width/2+rx*scale,py=rect.height/2+(ry*sp-z*cp)*scale;k?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.strokeStyle='#c97b08';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#6a746b';ctx.font='10px ui-monospace,monospace';ctx.fillText('ACTUAL TESSELLATED CAD EXPORT',17,25);ctx.fillText(phase.toUpperCase()+' · Ø'+checks[phase].center_hole_diameter_mm+' mm',17,rect.height-18)}function update(){const d=checks[phase];$('#cad-before').setAttribute('aria-pressed',phase==='before');$('#cad-after').setAttribute('aria-pressed',phase==='after');$('#bore-value').textContent='Ø'+d.center_hole_diameter_mm+' mm';$('#cad-valid').textContent=d.valid?'Valid':'Invalid';$('#solid-count').textContent=d.solids;$('#cad-volume').textContent=d.volume_mm3.toLocaleString('en-US',{maximumFractionDigits:2})+' mm³';$('#cad-removed').textContent=checks.edit.actual_volume_removed_mm3.toLocaleString('en-US',{maximumFractionDigits:2})+' mm³';$('#code-diameter').textContent=d.center_hole_diameter_mm.toFixed(1);$('#download-step').href='/data/cad/'+phase+'.step';$('#download-cad-source').href='/data/cad/'+phase+'.py';canvas.setAttribute('aria-label',`${phase} CAD solid, ${d.center_hole_diameter_mm} millimetre centre bore. Drag or use arrow keys to rotate.`);draw()}$('#cad-before').onclick=()=>{phase='before';update()};$('#cad-after').onclick=()=>{phase='after';update()};canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.009;pitch=Math.max(.3,Math.min(1.35,pitch+(e.clientY-drag[1])*.007));drag=[e.clientX,e.clientY];draw()};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null};canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home'){yaw=-.55;pitch=.9}else if(e.key==='ArrowLeft')yaw-=.12;else if(e.key==='ArrowRight')yaw+=.12;else pitch=Math.max(.3,Math.min(1.35,pitch+(e.key==='ArrowUp'?-.08:.08)));draw()};new ResizeObserver(draw).observe(canvas);update()}catch{ctx.font='14px Arial';ctx.fillText('Preview unavailable. Download the STEP file to inspect.',15,35);$('#cad-valid').textContent='See check record'}})()}
if($('#pcb-zoom')){(async()=>{const image=$('#inspection-image'),mask=new Image(),canvas=$('#pcb-zoom'),ctx=canvas.getContext('2d'),crop={x:480,y:690,width:310,height:240};let mode='original';try{await Promise.all([image.complete&&image.naturalWidth?Promise.resolve():new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject}),new Promise((resolve,reject)=>{mask.onload=resolve;mask.onerror=reject;mask.src='/data/inspection/pcb1_0_mask.png'})]);const raw=document.createElement('canvas');raw.width=mask.naturalWidth;raw.height=mask.naturalHeight;const rawctx=raw.getContext('2d');rawctx.drawImage(mask,0,0);const pixels=rawctx.getImageData(0,0,raw.width,raw.height),tint=rawctx.createImageData(raw.width,raw.height);let count=0,minX=raw.width,minY=raw.height,maxX=-1,maxY=-1;for(let y=0;y<raw.height;y++)for(let x=0;x<raw.width;x++){const i=(y*raw.width+x)*4;if(pixels.data[i]===255){count++;minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);tint.data[i]=242;tint.data[i+1]=167;tint.data[i+2]=36;tint.data[i+3]=190}}const overlay=document.createElement('canvas');overlay.width=raw.width;overlay.height=raw.height;overlay.getContext('2d').putImageData(tint,0,0);$('#pcb-positive').textContent=count.toLocaleString('en-US');$('#pcb-coverage').textContent=(count/(raw.width*raw.height)*100).toFixed(3)+'%';$('#pcb-bounds').textContent=`[${minX}, ${minY}, ${maxX+1}, ${maxY+1})`;const text={original:['Compare the bent leftmost pin with the adjacent straight pins.','Source feature','Bent leftmost connector pin. The paired binary annotation provides the reference anomalous region.'],reference:['Amber shows the supplied annotation over the same enlarged image.','Pixel-level reference','Amber displays the supplied mask over the original crop. Reference annotation, not model inference.'],binary:['White pixels are annotated anomaly; black pixels are background.','Binary encoding','This full-resolution mask has '+count.toLocaleString('en-US')+' positive pixels. The enlarged view shows the same mask cropped to the connector pins.']};function render(){ctx.imageSmoothingEnabled=mode!=='binary';ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(mode==='binary'?mask:image,crop.x,crop.y,crop.width,crop.height,0,0,canvas.width,canvas.height);if(mode==='reference')ctx.drawImage(overlay,crop.x,crop.y,crop.width,crop.height,0,0,canvas.width,canvas.height);['original','reference','binary'].forEach(m=>$('#pcb-'+m).setAttribute('aria-pressed',m===mode));$('#pcb-caption').textContent=text[mode][0];$('#pcb-takeaway-title').textContent=text[mode][1];$('#pcb-takeaway-text').textContent=text[mode][2];canvas.setAttribute('aria-label',text[mode][0])}['original','reference','binary'].forEach(m=>$('#pcb-'+m).onclick=()=>{mode=m;render()});render()}catch{$('#pcb-caption').textContent='Detail preview could not load. The original image and mask are available below.'}})()}
if($('#package-family')){const packages={robot:[{name:'Camera recording',file:'episode_000000.mp4',url:'/data/robot/episode_000000.mp4',type:'Source media',title:'What the robot observed',description:'The real camera recording from this task episode, with 28 frames at 5 Hz.',purpose:'Visual observations must correspond to the recorded steps so the model receives the right context.'},{name:'Recorded state and actions',file:'episode_000000.parquet',url:'/data/robot/episode_000000.parquet',type:'Structured records',title:'The values paired with each moment',description:'The original per-step records include state and action vectors, frame indices and timestamps.',purpose:'The task determines which observations and actions a model needs. Field meanings and units must be understood before training.'},{name:'Task instruction',file:'task_000000.json',url:'/data/robot/task_000000.json',type:'Task context',title:'What the demonstration is about',description:'The dataset-authored instruction identifies the task: put a small spoon from the basket to the tray.',purpose:'Language-conditioned models need the instruction linked to the relevant demonstration, not stored as an unrelated note.'},{name:'Provenance and checks',file:'manifest.json',url:'/data/robot/manifest.json',type:'Documentation',title:'An inspectable source trail',description:'The acquisition manifest records pinned sources, transformations, frame-count checks and file hashes.',purpose:'Your team can identify the sample version and understand how the displayed assets were prepared.'}],inspection:[{name:'Circuit-board image',file:'pcb1_0_image.jpg',url:'/data/inspection/pcb1_0_image.jpg',type:'Source image',title:'The inspection input',description:'A 1404 × 1070 pixel circuit-board test image from VisA.',purpose:'The source image preserves the visual context around the feature a detector is expected to locate.'},{name:'Reference annotation',file:'pcb1_0_mask.png',url:'/data/inspection/pcb1_0_mask.png',type:'Pixel-level label',title:'The region used for comparison',description:'A matching binary mask marks annotated anomaly pixels as 255 and background as 0.',purpose:'A reference region lets an evaluator distinguish correctly located, missed and extra predicted pixels.'},{name:'Sample documentation',file:'inspection-specimen.json',url:'/data/inspection/inspection-specimen.json',type:'Schema and provenance',title:'What the image and label mean',description:'The record identifies the sample, test split, dimensions, binary-label convention, source and usage rights.',purpose:'Clear label definitions and split identity help prevent misinterpretation and training–test leakage.'},{name:'Annotation measurements',file:'annotation-measurements.json',url:'/data/inspection/annotation-measurements.json',type:'Computed checks',title:'Measurements you can reproduce',description:'Pixel count, coverage and region bounds calculated from the supplied binary mask.',purpose:'These checks describe the annotation geometry and help verify alignment. They are not a detector performance score.'}],cad:[{name:'Editable model source',file:'before.py',url:'/data/cad/before.py',type:'Parametric construction',title:'A design recipe, not just a picture',description:'The CadQuery source specifies dimensions and operations for the starting model.',purpose:'An engineering task needs the representation the model will actually edit, with its parameters and tooling understood.'},{name:'Reference solid',file:'after.step',url:'/data/cad/after.step',type:'Solid-model exchange',title:'The result of the requested change',description:'A real exported STEP solid with the centre bore increased from 22 to 30 mm.',purpose:'A reference artifact makes the requested outcome inspectable beyond a screenshot.'},{name:'Request and geometric checks',file:'validation.json',url:'/data/cad/validation.json',type:'Task and evaluation',title:'The instruction tied to measured results',description:'The change request appears alongside solid validity, dimensions and measured volume for both states.',purpose:'Geometric checks establish bounded properties of the edit; design intent still needs appropriate engineering review.'},{name:'Source and usage rights',file:'ATTRIBUTION.txt',url:'/data/cad/ATTRIBUTION.txt',type:'Provenance',title:'Where the example came from',description:'Attribution, pinned source and the changes made to the Apache-2.0 CadQuery example.',purpose:'The artifact’s origin and permitted reuse remain traceable through the delivery.'}]};let active=0;function renderPackage(){const entries=packages[$('#package-family').value];$('#package-list').innerHTML=entries.map((e,i)=>`<button class="package-file" data-file-index="${i}" aria-pressed="${i===active}"><span>${e.name}<small>${e.file}</small></span><span aria-hidden="true">→</span></button>`).join('');const e=entries[active];$('#package-type').textContent=e.type;$('#package-title').textContent=e.title;$('#package-description').textContent=e.description;$('#package-purpose').textContent=e.purpose;$('#package-download').href=e.url;$('#package-download').setAttribute('download',e.file);renderPackagePreview($('#package-family').value,active);document.querySelectorAll('[data-file-index]').forEach(b=>b.onclick=()=>{active=Number(b.dataset.fileIndex);renderPackage();document.querySelector(`[data-file-index="${active}"]`).focus()})}$('#package-family').onchange=()=>{active=0;renderPackage()};renderPackage()}

// Link each visible specimen to its matching delivery package.
document.querySelectorAll("[data-package]").forEach(a=>a.addEventListener("click",()=>{const select=document.querySelector("#package-family");select.value=a.dataset.package;select.dispatchEvent(new Event("change",{bubbles:true}));}));
